class TTLCache:
    def __init__(self, maxsize, clock):
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        self.maxsize = maxsize
        self.clock = clock
        self._store = {}  # key -> (value, expiry)
        self._order = []  # list of keys in LRU order (least recent first)

    def _purge_expired(self):
        now = self.clock()
        expired = [k for k in self._order if self._store[k][1] <= now]
        for k in expired:
            del self._store[k]
        if expired:
            self._order = [k for k in self._order if k not in set(expired)]

    def set(self, key, value, ttl):
        if ttl <= 0:
            # Non-positive TTL must not remain stored
            if key in self._store:
                del self._store[key]
                if key in self._order:
                    self._order.remove(key)
            return
        expiry = self.clock() + ttl
        if key in self._store:
            # Update existing entry
            self._store[key] = (value, expiry)
            # Move to most recent
            if key in self._order:
                self._order.remove(key)
            self._order.append(key)
        else:
            # New entry
            self._store[key] = (value, expiry)
            self._order.append(key)
            # Check capacity
            if len(self._store) > self.maxsize:
                self._purge_expired()
                if len(self._store) > self.maxsize:
                    # Evict LRU live item
                    while self._order:
                        lru_key = self._order.pop(0)
                        if lru_key in self._store:
                            del self._store[lru_key]
                            break

    def get(self, key, default=None):
        if key not in self._store:
            return default
        value, expiry = self._store[key]
        if self.clock() >= expiry:
            # Expired
            del self._store[key]
            if key in self._order:
                self._order.remove(key)
            return default
        # Refresh LRU recency
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)
        return value

