import asyncio
from typing import Any, AsyncIterable, Awaitable, Callable, Iterable, List


async def async_map_ordered(
    items: Iterable[Any],
    worker: Callable[[Any], Awaitable[Any]],
    limit: int,
) -> List[Any]:
    if limit < 1:
        raise ValueError("limit must be >= 1")

    # Convert to list to support any finite iterable
    items_list = list(items)
    n = len(items_list)
    results: List[Any] = [None] * n

    if n == 0:
        return results

    async def run_task(index: int, item: Any) -> None:
        results[index] = await worker(item)

    tasks: List[asyncio.Task] = []
    try:
        for i, item in enumerate(items_list):
            if len(tasks) >= limit:
                # Wait for at least one task to complete before adding more
                done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
                # Remove completed tasks from the list
                for t in done:
                    tasks.remove(t)
                # Check if any completed task raised an exception
                for t in done:
                    if t.exception() is not None:
                        raise t.exception()
            task = asyncio.ensure_future(run_task(i, item))
            tasks.append(task)

        # Wait for all remaining tasks
        if tasks:
            done, pending = await asyncio.wait(tasks)
            for t in done:
                if t.exception() is not None:
                    raise t.exception()
    except Exception:
        # Cancel all outstanding tasks and await them
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        raise

    return results

