import copy

def deep_merge(base, overlay):
    """
    Deep merge two dictionaries.
    - Returns a new dictionary (deep copy merge).
    - Does not mutate or alias either input.
    - Recursively merges values only when both corresponding values are dicts.
    - An overlay value of None deletes that key.
    - Lists and all other values replace the base value and are deep-copied.
    """
    result = {}
    for key in base:
        if key in overlay:
            if overlay[key] is None:
                continue
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = deep_merge(base_val, overlay_val)
            else:
                result[key] = copy.deepcopy(overlay_val)
        else:
            result[key] = copy.deepcopy(base[key])
    for key in overlay:
        if key not in base:
            if overlay[key] is None:
                continue
            result[key] = copy.deepcopy(overlay[key])
    return result

